  <script>
    (() => {
      "use strict";

      const desktop = document.getElementById("desktop");
      const filesWindow = document.getElementById("files-window");
      const notepadWindow = document.getElementById("notepad-window");
      const openFiles = document.getElementById("open-files");
      const openNotepad = document.getElementById("open-notepad");
      let topZ = 30;

      function focusWindow(win) {
        document.querySelectorAll(".window").forEach(item => {
          item.classList.toggle("active-window", item === win);
        });
        win.style.zIndex = String(++topZ);
      }

      function showWindow(win) {
        win.hidden = false;
        focusWindow(win);
      }

      openFiles.addEventListener("click", () => showWindow(filesWindow));
      openNotepad.addEventListener("click", () => {
        showWindow(notepadWindow);
        requestAnimationFrame(() => document.getElementById("editor").focus());
      });

      document.querySelectorAll(".win-close").forEach(button => {
        button.addEventListener("click", event => {
          const win = event.currentTarget.closest(".window");
          win.hidden = true;
          win.classList.remove("active-window");
        });
      });

      document.querySelectorAll(".window").forEach(win => {
        win.addEventListener("pointerdown", () => focusWindow(win));

        const bar = win.querySelector(".titlebar");
        let drag = null;

        bar.addEventListener("pointerdown", event => {
          if (event.target.closest("button")) return;
          const rect = win.getBoundingClientRect();
          drag = {
            pointerId: event.pointerId,
            dx: event.clientX - rect.left,
            dy: event.clientY - rect.top
          };
          bar.setPointerCapture(event.pointerId);
          focusWindow(win);
          event.preventDefault();
        });

        bar.addEventListener("pointermove", event => {
          if (!drag || drag.pointerId !== event.pointerId) return;

          const maxLeft = Math.max(0, desktop.clientWidth - win.offsetWidth);
          const maxTop = Math.max(30, desktop.clientHeight - win.offsetHeight);
          const left = Math.min(maxLeft, Math.max(0, event.clientX - drag.dx));
          const top = Math.min(maxTop, Math.max(30, event.clientY - drag.dy));

          win.style.left = left + "px";
          win.style.top = top + "px";
        });

        const stopDrag = event => {
          if (drag && drag.pointerId === event.pointerId) {
            drag = null;
          }
        };

        bar.addEventListener("pointerup", stopDrag);
        bar.addEventListener("pointercancel", stopDrag);
      });

      function updateClock() {
        const now = new Date();
        document.getElementById("panel-clock").textContent =
          new Intl.DateTimeFormat(undefined, {
            weekday: "short",
            month: "short",
            day: "numeric",
            hour: "2-digit",
            minute: "2-digit"
          }).format(now);
      }

      updateClock();
      setInterval(updateClock, 30000);

      const fileSystem = {
        "/": [
          { name: "bin", type: "folder" },
          { name: "etc", type: "folder" },
          { name: "home", type: "folder" },
