        ],
        "/usr/bin": [
          { name: "python3", type: "file" },
          { name: "nano", type: "file" }
        ],
        "/usr/lib": [],
        "/usr/share": [],
        "/var": [
          { name: "log", type: "folder" },
          { name: "tmp", type: "folder" }
        ],
        "/var/log": [
          { name: "system.log", type: "file" },
          { name: "auth.log", type: "file" }
        ],
        "/var/tmp": []
      };

      const filesPath = document.getElementById("files-path");
      const filesList = document.getElementById("files-list");
      const filesUp = document.getElementById("files-up");
      const filesStatus = document.getElementById("files-status");
      let currentPath = "/";

      function joinPath(parent, child) {
        return parent === "/" ? "/" + child : parent + "/" + child;
      }

      function renderDirectory() {
        filesPath.textContent = currentPath;
        filesUp.disabled = currentPath === "/";
        filesList.replaceChildren();

        const entries = fileSystem[currentPath] || [];
        entries.forEach(entry => {
          const item = document.createElement("button");
          item.type = "button";
          item.className = "fs-item " + entry.type;
          item.dataset.name = entry.name;
          item.dataset.type = entry.type;
          item.title = entry.type === "folder"
            ? "Double-click to open " + entry.name
            : entry.name;

          const label = document.createElement("span");
          label.textContent = entry.name;
          item.appendChild(label);

          item.addEventListener("click", () => {
            filesList.querySelectorAll(".fs-item").forEach(other => {
              other.classList.toggle("selected", other === item);
            });
            filesStatus.textContent = entry.name + " — " + entry.type;
          });

          item.addEventListener("dblclick", () => {
            if (entry.type === "folder") {
              currentPath = joinPath(currentPath, entry.name);
              renderDirectory();
            } else {
              filesStatus.textContent = "Opened " + entry.name + " (read-only fake file)";
            }
          });

          filesList.appendChild(item);
        });

        filesStatus.textContent = entries.length === 1
          ? "1 item"
          : entries.length + " items";
      }

      filesUp.addEventListener("click", () => {
        if (currentPath === "/") return;
        const pieces = currentPath.split("/").filter(Boolean);
        pieces.pop();
        currentPath = pieces.length ? "/" + pieces.join("/") : "/";
        renderDirectory();
      });

      renderDirectory();

      const STORAGE_KEY = "ubuntu-desktop-notepad-tabs-v1";
      const tabsElement = document.getElementById("tabs");
      const newTabButton = document.getElementById("new-tab");
      const editor = document.getElementById("editor");
      const documentStatus = document.getElementById("document-status");
      const cursorStatus = document.getElementById("cursor-status");

      let notepadState = loadNotepadState();

      function freshState() {
        return {
          activeId: "tab-1",
          nextNumber: 2,
          tabs: [
            { id: "tab-1", title: "Untitled 1", content: "" }
          ]
        };
      }

      function loadNotepadState() {
        try {
          const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (
            parsed &&
            Array.isArray(parsed.tabs) &&
            parsed.tabs.length > 0 &&
            parsed.tabs.every(tab =>
              typeof tab.id === "string" &&
              typeof tab.title === "string" &&
              typeof tab.content === "string"
            )
          ) {
            if (!parsed.tabs.some(tab => tab.id === parsed.activeId)) {
              parsed.activeId = parsed.tabs[0].id;
            }
            if (!Number.isInteger(parsed.nextNumber) || parsed.nextNumber < 1) {
              parsed.nextNumber = parsed.tabs.length + 1;
            }
            return parsed;
          }
        } catch (error) {
          console.warn("Could not restore notepad data:", error);
        }
        return freshState();
      }

      function saveNotepadState() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(notepadState));
          documentStatus.textContent = "Saved locally";
        } catch (error) {
          documentStatus.textContent = "Storage unavailable";
        }
      }

      function getActiveTab() {
        return notepadState.tabs.find(tab => tab.id === notepadState.activeId);
      }

      function renderTabs() {
        tabsElement.replaceChildren();

        notepadState.tabs.forEach(tabData => {
          const tab = document.createElement("button");
          tab.type = "button";
          tab.className = "tab" + (tabData.id === notepadState.activeId ? " active" : "");
          tab.textContent = tabData.title;
          tab.dataset.tabId = tabData.id;
          tab.setAttribute("role", "tab");
          tab.setAttribute("aria-selected", String(tabData.id === notepadState.activeId));

          tab.addEventListener("click", () => {
            notepadState.activeId = tabData.id;
            renderTabs();
            showActiveContent();
            saveNotepadState();
            editor.focus();
          });

          tabsElement.appendChild(tab);
        });
      }

      function showActiveContent() {
        const active = getActiveTab();
        editor.value = active ? active.content : "";
        updateCursorStatus();
      }

      function createTab() {
        const number = notepadState.nextNumber++;
        const tab = {
          id: "tab-" + Date.now() + "-" + number,
          title: "Untitled " + number,
          content: ""
        };
        notepadState.tabs.push(tab);
        notepadState.activeId = tab.id;
        renderTabs();
        showActiveContent();
        saveNotepadState();
        editor.focus();
      }

      editor.addEventListener("input", () => {
        const active = getActiveTab();
        if (active) {
          active.content = editor.value;
          saveNotepadState();
        }
        updateCursorStatus();
      });

      function updateCursorStatus() {
        const beforeCaret = editor.value.slice(0, editor.selectionStart);
        const lines = beforeCaret.split("\n");
        cursorStatus.textContent =
          "Ln " + lines.length + ", Col " + (lines[lines.length - 1].length + 1);
      }

      editor.addEventListener("click", updateCursorStatus);
      editor.addEventListener("keyup", updateCursorStatus);
      editor.addEventListener("select", updateCursorStatus);
      newTabButton.addEventListener("click", createTab);

      renderTabs();
      showActiveContent();
      saveNotepadState();

      window.addEventListener("beforeunload", saveNotepadState);
    })();
  </script>
